import{_ as a,o as t,c as o,al as r}from"./chunks/framework.BawR2jEz.js";const u=JSON.parse('{"title":"Рубрика «Категория exDoc»","description":"Настройка рубрики категории — структура полей и шаблон отображения для категорий exDoc.","frontmatter":{"title":"Рубрика «Категория exDoc»","description":"Настройка рубрики категории — структура полей и шаблон отображения для категорий exDoc."},"headers":[],"relativePath":"rubrics/exdoc-category/index.md","filePath":"rubrics/exdoc-category/index.md"}'),d={name:"rubrics/exdoc-category/index.md"};function c(i,e,h,n,l,s){return t(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="рубрика-«категория-exdoc»" tabindex="-1">Рубрика «Категория exDoc» <a class="header-anchor" href="#рубрика-«категория-exdoc»" aria-label="Permalink to &quot;Рубрика «Категория exDoc»&quot;">​</a></h1><p>Тип: <code>rub_exdoc_category</code></p><p>Рубрика категории определяет структуру полей и шаблон отображения для категорий exDoc. Категории — это разделы, в которые группируются документы. Одна рубрика категории задаёт единый вид для всех категорий, привязанных к ней.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Название</strong></td><td>Имя рубрики (например, «Категории блога»)</td></tr><tr><td><strong>Хэштег</strong></td><td>Уникальный идентификатор</td></tr><tr><td><strong>Шаблон-обёртка</strong></td><td>Header/footer — каркас страницы</td></tr><tr><td><strong>Статус</strong></td><td>Включена/выключена</td></tr></tbody></table><h2 id="разделы-формы" tabindex="-1">Разделы формы <a class="header-anchor" href="#разделы-формы" aria-label="Permalink to &quot;Разделы формы&quot;">​</a></h2><h3 id="поля-рубрики" tabindex="-1">Поля рубрики <a class="header-anchor" href="#поля-рубрики" aria-label="Permalink to &quot;Поля рубрики&quot;">​</a></h3><p>Определение полей категории. Подробнее см. <a href="/exdoc-docs/fields/">Поля</a>.</p><h3 id="макет-страницы" tabindex="-1">Макет страницы <a class="header-anchor" href="#макет-страницы" aria-label="Permalink to &quot;Макет страницы&quot;">​</a></h3><p>Twig-шаблон страницы категории. Используется <a href="/exdoc-docs/editor/">Редактор</a> с вкладками: шаблон, стили (SCSS), JavaScript, подключение ссылок, язык. Внутри шаблона доступен <a href="./context.html">объект контекста категории</a> со свойствами и методами (<code>fld()</code>, <code>getCategoryDocuments()</code>, <code>getSubCategories()</code> и др.).</p><h3 id="макеты-полеи" tabindex="-1">Макеты полей <a class="header-anchor" href="#макеты-полеи" aria-label="Permalink to &quot;Макеты полей&quot;">​</a></h3><p>Twig-шаблоны для каждого поля рубрики. Определяют, как отдельное поле рендерится на фронте.</p><h3 id="макеты-превью" tabindex="-1">Макеты превью <a class="header-anchor" href="#макеты-превью" aria-label="Permalink to &quot;Макеты превью&quot;">​</a></h3><p>Шаблоны миниатюр для отображения категорий в списках. Каждый thumb — со своим шаблоном, стилями и скриптами. Вызываются через <code>ex.rubric_thumb()</code>.</p><h3 id="компоненты" tabindex="-1">Компоненты <a class="header-anchor" href="#компоненты" aria-label="Permalink to &quot;Компоненты&quot;">​</a></h3><p>Переиспользуемые Twig-фрагменты, доступные через <code>{{ component(&#39;hashtag&#39;) }}</code>.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./context.html">Объект контекста категории</a> — свойства и методы в шаблоне</li><li><a href="/exdoc-docs/rubrics/exdoc-document/">Рубрика «Документ exDoc»</a> — шаблон документа</li><li><a href="/exdoc-docs/fields/">Поля</a> — типы полей</li></ul></div>',1)])])}const b=a(d,[["render",c]]);export{u as __pageData,b as default};
